use std::process::exit;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params {
    count: u32,
    dt: f32,
}

@group(0) @binding(0) var<storage, read_write> pos: array<vec2<f32>>;
@group(0) @binding(1) var<storage, read_write> vel: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read_write> acc: array<vec2<f32>>;
@group(0) @binding(3) var<uniform> params: Params;

@compute @workgroup_size(64)
fn accelerate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let pi = pos[i];
    var a = vec2<f32>(0.0, 0.0);
    for (var j = 0u; j < params.count; j = j + 1u) {
        if (j == i) {
            continue;
        }
        let d = pos[j] - pi;
        let r2 = dot(d, d) + 0.01;
        a = a + d / (r2 * sqrt(r2));
    }
    acc[i] = a;
}

@compute @workgroup_size(64)
fn integrate(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let v = vel[i] + acc[i] * params.dt;
    vel[i] = v;
    pos[i] = pos[i] + v * params.dt;
}
"#;

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    count: u32,
    dt: f32,
    _pad: [u32; 2],
}

struct Input {
    steps: u32,
    dt: f32,
    pos: Vec<[f32; 2]>,
    vel: Vec<[f32; 2]>,
}

fn parse(text: &str) -> Result<Input, String> {
    let mut it = text.split_whitespace();
    let mut next = |what: &str| -> Result<f64, String> {
        it.next()
            .ok_or_else(|| format!("missing {what}"))?
            .parse::<f64>()
            .map_err(|e| format!("bad {what}: {e}"))
    };
    let count = next("count")? as usize;
    let steps = next("steps")? as u32;
    let dt = next("dt")? as f32;
    let mut pos = Vec::with_capacity(count);
    let mut vel = Vec::with_capacity(count);
    for _ in 0..count {
        let x = next("x")? as f32;
        let y = next("y")? as f32;
        let vx = next("vx")? as f32;
        let vy = next("vy")? as f32;
        pos.push([x, y]);
        vel.push([vx, vy]);
    }
    Ok(Input { steps, dt, pos, vel })
}

fn run_gpu(input: &Input) -> Result<(Vec<[f32; 2]>, Vec<[f32; 2]>), String> {
    let n = input.pos.len();
    let instance = wgpu::Instance::default();
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        force_fallback_adapter: false,
        compatible_surface: None,
    }))
    .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let size = (n * 8) as u64;
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let pos_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("pos"),
        contents: bytemuck::cast_slice(&input.pos),
        usage: storage,
    });
    let vel_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("vel"),
        contents: bytemuck::cast_slice(&input.vel),
        usage: storage,
    });
    let acc_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("acc"),
        size,
        usage: storage,
        mapped_at_creation: false,
    });
    let params = Params { count: n as u32, dt: input.dt, _pad: [0; 2] };
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::bytes_of(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let read_pos = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("read_pos"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    let read_vel = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("read_vel"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("particles"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = |entry: &'static str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry),
            layout: None,
            module: &module,
            entry_point: Some(entry),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let accel_pipe = pipeline("accelerate");
    let integ_pipe = pipeline("integrate");
    let entries = [
        wgpu::BindGroupEntry { binding: 0, resource: pos_buf.as_entire_binding() },
        wgpu::BindGroupEntry { binding: 1, resource: vel_buf.as_entire_binding() },
        wgpu::BindGroupEntry { binding: 2, resource: acc_buf.as_entire_binding() },
        wgpu::BindGroupEntry { binding: 3, resource: params_buf.as_entire_binding() },
    ];
    let bind = |p: &wgpu::ComputePipeline| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &p.get_bind_group_layout(0),
            entries: &entries,
        })
    };
    let accel_bind = bind(&accel_pipe);
    let integ_bind = bind(&integ_pipe);

    let groups = (n as u32).div_ceil(64);
    let mut encoder = device.create_command_encoder(&Default::default());
    for _ in 0..input.steps {
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&accel_pipe);
            pass.set_bind_group(0, &accel_bind, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
        {
            let mut pass = encoder.begin_compute_pass(&Default::default());
            pass.set_pipeline(&integ_pipe);
            pass.set_bind_group(0, &integ_bind, &[]);
            pass.dispatch_workgroups(groups, 1, 1);
        }
    }
    encoder.copy_buffer_to_buffer(&pos_buf, 0, &read_pos, 0, size);
    encoder.copy_buffer_to_buffer(&vel_buf, 0, &read_vel, 0, size);
    queue.submit(Some(encoder.finish()));

    read_pos.slice(..).map_async(wgpu::MapMode::Read, |_| {});
    read_vel.slice(..).map_async(wgpu::MapMode::Read, |_| {});
    device
        .poll(wgpu::PollType::Wait)
        .map_err(|e| format!("poll failed: {e}"))?;
    let fetch = |b: &wgpu::Buffer| -> Vec<[f32; 2]> {
        let data = b.slice(..).get_mapped_range();
        bytemuck::cast_slice::<u8, [f32; 2]>(&data).to_vec()
    };
    Ok((fetch(&read_pos), fetch(&read_vel)))
}

fn main() {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: particles <input-file>");
        exit(1);
    };
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        eprintln!("cannot read {path}: {e}");
        exit(1);
    });
    let input = parse(&text).unwrap_or_else(|e| {
        eprintln!("{e}");
        exit(1);
    });
    if input.pos.is_empty() {
        eprintln!("no particles");
        exit(1);
    }
    let (pos, vel) = run_gpu(&input).unwrap_or_else(|e| {
        eprintln!("{e}");
        exit(1);
    });

    let n = pos.len() as f64;
    let cx = pos.iter().map(|p| p[0] as f64).sum::<f64>() / n;
    let cy = pos.iter().map(|p| p[1] as f64).sum::<f64>() / n;
    let mx: f64 = vel.iter().map(|v| v[0] as f64).sum();
    let my: f64 = vel.iter().map(|v| v[1] as f64).sum();
    let kinetic: f64 = vel
        .iter()
        .map(|v| (v[0] as f64 * v[0] as f64 + v[1] as f64 * v[1] as f64) / 2.0)
        .sum();
    let spread = (pos
        .iter()
        .map(|p| (p[0] as f64 - cx).powi(2) + (p[1] as f64 - cy).powi(2))
        .sum::<f64>()
        / n)
        .sqrt();
    println!("CENTER {cx:.6} {cy:.6}");
    println!("MOMENTUM {mx:.6} {my:.6}");
    println!("KINETIC {kinetic:.6}");
    println!("SPREAD {spread:.6}");
}
